PARAM_DEFS = {0: ('imu_enable', 'BNO086 IMU present (SPI). 0 = skip init/poll and stop gating STARTUP/CALIBRATION/RUNNING on it; also blocks RUNNING since real pitch feedback is required. Persisted; takes effect at boot (needs reboot).'), 3: ('buzzer_volume', 'Buzzer master volume. 0.0 = silent, 1.0 = max, scales linearly in between. Persisted; takes effect at boot.'), 4: ('led_enable', 'Status RGB LED present. 0 = skip init/poll. Persisted; takes effect at boot.'), 5: ('hip_l_enable', 'Left AK45 hip motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 6: ('hip_r_enable', 'Right AK45 hip motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 7: ('wheel_l_enable', 'Left ODrive wheel motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 8: ('wheel_r_enable', 'Right ODrive wheel motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 9: ('watchdog_enable', 'Enable hardware watchdog (WDOG1) — auto-reboots the MCU if the main loop stalls. Default off. Takes effect at boot; once armed cannot be disabled in software until the next reset.'), 10: ('loop_profile_enable', 'Debug: log a rolling max of loop()-section timings once/sec. Not persisted.'), 513: ('hip_running_kp', 'MIT position gain used for hip setpoints while RUNNING.'), 514: ('hip_running_kd', 'MIT damping gain used for hip setpoints while RUNNING.'), 515: ('hip_running_tff', 'MIT feedforward torque used for hip setpoints while RUNNING.'), 516: ('hip_running_ramp_s', 'Seconds to ramp kp/tff from 0 to their running value after entering RUNNING, easing in instead of snapping. kd applies at full value throughout. 0 = no ramp.'), 512: ('estop_hip_disable', '1 = exit MIT mode on ESTOP entry and re-enter on reset; 0 = leave MIT running through ESTOP.'), 288: ('calib_seek_speed', 'Slow position-ramp speed toward the retract limit switch [rad/s].'), 289: ('calib_move_speed', 'Slow position-ramp speed while releasing and backing away from the switch [rad/s].'), 290: ('calib_seek_kp', 'Weak MIT position-gain target while seeking toward the retract switch; authority slews up from zero over calib_rampdown_s.'), 291: ('calib_kd', 'MIT damping gain used for all switch-homing motion.'), 292: ('calib_seek_cur_lim', 'Measured motor-current safety threshold while seeking toward the retract switch [A]; it must be exceeded continuously for calib_cur_trip_ms before calibration fails.'), 293: ('calib_move_cur_lim', 'Measured motor-current safety threshold while moving away from an initially pressed retract switch or backing off after zeroing [A]; it must be exceeded continuously for calib_cur_trip_ms before calibration fails.'), 294: ('calib_backoff_rad', 'Actual encoder distance the hip must move away from the switch during initial clearance and after homing [rad]; default 5 degrees.'), 295: ('calib_range_l_rad', 'Left hip extended software limit as an angular delta from retract-switch zero [rad].'), 296: ('calib_range_r_rad', 'Right hip extended software limit as an angular delta from retract-switch zero [rad].'), 297: ('calib_seek_timeout', 'Maximum time to seek a retract switch before calibration faults [s].'), 298: ('calib_release_to', 'Maximum time allowed for an initially or newly pressed switch to release [s].'), 299: ('calib_max_seek_rad', 'Maximum commanded travel while seeking a retract switch before calibration faults [rad].'), 300: ('calib_max_rel_rad', 'Maximum commanded travel allowed while moving away from a retract switch; must be at least calib_backoff_rad [rad].'), 301: ('calib_cur_trip_ms', 'Continuous time motor current must remain above the active calibration current limit before faulting [ms]; 0 restores immediate trips.'), 302: ('calib_move_kp', 'MIT position-gain target while moving away from the retract switch against robot weight; uses the same calib_rampdown_s authority slew.'), 303: ('calib_rampdown_s', 'Seconds for calibration Kp to slew up from zero and for Kp/Kd to ramp back to zero at successful completion or operator cancellation; 0 disables ramping.'), 305: ('calib_bypass_en', '1 = allow RUNNING without completed switch calibration or valid hip limits; dangerous bench-test bypass.'), 768: ('wm_enc_timeout_ms', "Wheel encoder feedback watchdog timeout [ms]; increase if CAN is flaky. ODrive PID gains aren't exposed here — tune via the ODrive USB GUI (CAN can't reach those properties on 0.5.x)."), 1024: ('lqr_enable', '1 = wheel torque output active; 0 = LQR runs but outputs zero.'), 1025: ('sim_pitch_rad', 'Pitch value injected in place of real IMU pitch when enable_sim_pitch=1.'), 1026: ('lqr_torque_limit', "|tau_sym| clamp [N·m]; hard max 7.0. READONLY — slewed automatically from the active CH9 speed profile's torque_lim. Edit profile1/2/3_torque_lim instead."), 1027: ('wm_vel_limit', 'Per-tick soft wheel velocity governor [turns/s]; ESTOP at 2x this.'), 1028: ('vel_pi_en', '1 = velocity PI active; 0 = theta_ref fixed at 0.'), 1029: ('vel_pi_kp', 'Velocity PI proportional gain [rad/(m/s)].'), 1030: ('vel_pi_ki', 'Velocity PI integral gain [rad/m].'), 1031: ('vel_pi_kff', 'Velocity PI acceleration feedforward gain [s²·rad/m] (≈ 1/g).'), 1033: ('vel_pi_rate_lim', 'theta_ref slew rate limit [rad/s].'), 1034: ('vel_pi_int_max', 'Velocity PI integrator anti-windup clamp [rad·s].'), 1035: ('v_cmd_ms', 'Desired forward velocity setpoint [m/s]; GUI/Phase3 testing.'), 1036: ('yaw_pi_en', '1 = yaw PI active; 0 = tau_yaw fixed at 0.'), 1037: ('yaw_pi_kp', 'Yaw PI proportional gain [N·m/(rad/s)].'), 1038: ('yaw_pi_ki', 'Yaw PI integral gain [N·m/rad].'), 1039: ('yaw_pi_torque_max', '|tau_yaw| clamp [N·m].'), 1040: ('yaw_pi_int_max', 'Yaw PI integrator anti-windup [N·m·s].'), 1041: ('omega_cmd_rds', 'Desired yaw rate [rad/s]; positive = CCW from above.'), 1042: ('ff1_alpha', 'Hip reaction cancel feedforward gain [0–1]; start at 0, ramp up.'), 1043: ('ff2_alpha', 'Gravity compensation feedforward gain [0–1]; start at 0, ramp up.'), 1044: ('ff1_kt_hip', 'AK45-10 hip motor output torque constant [N·m/A]; hardware characteristic, not a tuning knob. READONLY, edit + reflash to change.'), 1045: ('jump_enable', 'Master gate for jump sequence: 0 = no-op, 1 = execute.'), 1046: ('jump_torque_max', 'Max hip feedforward torque during EXTEND [N·m]; ramp up from 0.'), 1047: ('jump_crouch_time', 'CROUCH phase duration [s].'), 1048: ('jump_ramp_up', 'EXTEND torque softstart duration [s].'), 1049: ('jump_ramp_down', 'Torque→zero zone near the extended limit [rad].'), 1050: ('jump_omega_max', 'Hip velocity above which feedforward torque → 0 [rad/s].'), 1051: ('jump_hs_margin', 'Hard cutoff margin from the configured extended hip software limit [rad].'), 1052: ('jump_kp', 'Position gain for CROUCH/RETRACT phases.'), 1053: ('jump_kd', 'Damping for CROUCH/RETRACT phases.'), 1054: ('jump_ext_kd', 'Small damping during EXTEND (electrical damping only).'), 1055: ('jump_ext_timeout', 'Max time in EXTEND before forced RETRACT [s].'), 1056: ('enable_sim_pitch', '1 = use sim_pitch_rad instead of real IMU pitch.'), 1057: ('sim_pitch_rate', 'Pitch rate injected in place of real IMU pitch rate when enable_sim_prate=1 [rad/s].'), 1058: ('enable_sim_prate', '1 = use sim_pitch_rate instead of real IMU pitch rate.'), 1059: ('pitch_watchdog_en', "1 = ESTOP (FAULT_PITCH_WATCHDOG) if pitch exceeds pitch_watchdog_fwd_ret/ext or pitch_watchdog_bwd_ret/ext (gain-scheduled by leg height) for > 200 ms. Default on and NOT persisted — always starts back on after reboot so a bench-test disable can't silently survive into a real run."), 1060: ('lqr_k_pitch_ret', 'LQR pitch gain, fully retracted leg. Default -0.3 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1061: ('lqr_k_rate_ret', 'LQR pitch-rate gain, fully retracted leg. Default -0.1 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1062: ('lqr_k_pitch_ext', 'LQR pitch gain, fully extended leg. Default -0.3 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1063: ('lqr_k_rate_ext', 'LQR pitch-rate gain, fully extended leg. Default -0.1 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1064: ('lqr_k_vel', 'LQR velocity-error gain, invariant across leg height. Default -0.007.'), 1065: ('run_wheel_bypass_en', '1 = allow RUNNING mode to arm with wheel_l/r_enable off (bench-test only, e.g. a software-triggered smoke test with hips also disabled, no real torque anywhere). Independent of calib_bypass_en, which only covers the hip check. Not persisted — always boots to 0 (bypass off).'), 1066: ('alpha_force_ret_en', '1 = force the hip gain-schedule blend to alpha=0.0 (fully-retracted LQR gains), bypassing the hm_limits valid-calibration check entirely. For hardware tuning at the retracted anchor without needing a completed calibration. Persistent — survives reboot, so a bench session left with this on stays on until explicitly cleared.'), 1067: ('gui_motion_ctrl_en', '1 = v_cmd_ms/omega_cmd_rds are driven by GUI/CLI param_set instead of CH2/CH4; radio arming (CH10) is unaffected. Auto-clears (reverting to radio control) if no GUI command arrives for 300 ms. Not persisted — always boots to 0.'), 1068: ('standup_enable', "Master gate: 0 = arm goes STANDBY->RUNNING directly (today's behavior). 1 = arm routes through STANDING_UP recovery first. Default 0."), 1069: ('standup_pitch_fwd', 'Arm-time gate: max forward pitch [rad] considered recoverable. Default 0.6 (~34°).'), 1070: ('standup_pitch_bwd', 'Arm-time gate: max backward pitch [rad] considered recoverable. Default 0.6 (~34°).'), 1071: ('standup_crouch_kp', 'Hip MIT position gain during the CROUCH ramp, held through RECOVER/PAUSE. Mirrors jump_kp.'), 1072: ('standup_crouch_kd', 'Hip MIT damping gain, same phases. Mirrors jump_kd.'), 1073: ('standup_crouch_time', 'CROUCH phase (leg retraction) duration [s]. Default 0.30.'), 1074: ('standup_k_pitch', 'Recovery P gain on pitch [N·m/rad], same positive-sign convention as the LQR/FF2 terms. Starts at 0 — tune up on the bench.'), 1075: ('standup_k_rate', 'Recovery D gain on pitch rate. Starts at 0 — tune up on the bench.'), 1076: ('standup_torque_lim', '|tau_recover| clamp [N·m], applied before the hard MOTOR_TRQ_MAX clamp. Starts at 0 — tune up on the bench; max = MOTOR_TRQ_MAX (7.0).'), 1077: ('standup_vel_limit', "Dedicated runaway-backup baseline [turns/s], trips at 2x — independent of wm_vel_limit so tuning one doesn't loosen the other's margin."), 1078: ('standup_cap_pitch', '|pitch| below this [rad] (+ rate below standup_cap_rate) for the hold time => captured (handoff to RUNNING).'), 1079: ('standup_cap_rate', '|pitch_rate| capture threshold [rad/s].'), 1080: ('standup_cap_hold', 'Continuous in-band duration [s] required before handoff.'), 1081: ('standup_timeout', 'Max time [s] in one RECOVER attempt before declaring it failed-to-converge (not diverged).'), 1082: ('standup_max_retries', 'Retry attempts after the first (total attempts = this + 1); integer stored as a float.'), 1083: ('standup_retry_pause', 'Wheels-off settle time [s] between retry attempts.'), 1084: ('lqr_pitch_trim_ret', "Balance-point pitch offset [rad], fully retracted leg (alpha=0). The lean the LQR holds for zero velocity, compensating a CG that is not exactly over the wheel axle. Interpolated toward lqr_pitch_trim_ext by the gain-schedule alpha. Default -0.14 rad (~-8 deg), measured on the bench 2026-07-25: with this at 0 the vel-PI integrator was doing the trim's job, permanently eating ~8 deg of the backward lean budget. Not currently a live-tune target (see LIVE_TUNE_SLOTS in main.cpp) — edit via the Params tab, or repoint a live-tune slot at this param for a future bench session."), 1085: ('lqr_pitch_trim_ext', 'Balance-point pitch offset [rad], fully extended leg (alpha=1). Companion to lqr_pitch_trim_ret; the two are linearly interpolated by the gain-schedule alpha (higher order later if needed).'), 1086: ('theta_max_fwd_ret', 'Velocity-PI commanded-lean clamp, forward direction, fully retracted leg [rad, magnitude]. theta_ref is clamped to +this value when leaning forward (pitch positive = lean forward). Gain-scheduled toward vel_pi_theta_max_fwd_ext by the same alpha as the LQR gains. Split from vel_pi_theta_max because the leg linkage clears the ground at a different forward angle than backward.'), 1087: ('theta_max_bwd_ret', 'Velocity-PI commanded-lean clamp, backward direction, fully retracted leg [rad, magnitude]. theta_ref is clamped to -this value when leaning backward. Gain-scheduled toward vel_pi_theta_max_bwd_ext by the same alpha as the LQR gains. Split from vel_pi_theta_max because the leg linkage clears the ground at a different backward angle than forward.'), 1088: ('theta_max_fwd_ext', 'Velocity-PI commanded-lean clamp, forward direction, fully extended leg [rad, magnitude]. Companion to vel_pi_theta_max_fwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1089: ('theta_max_bwd_ext', 'Velocity-PI commanded-lean clamp, backward direction, fully extended leg [rad, magnitude]. Companion to vel_pi_theta_max_bwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1090: ('pitch_wd_fwd_ret', 'Pitch watchdog forward trip threshold, fully retracted leg [rad, magnitude]. ESTOPs (FAULT_PITCH_WATCHDOG) if pitch > this value for > 200 ms (pitch positive = lean forward). Gain-scheduled toward pitch_watchdog_fwd_ext by the same alpha as the LQR gains. Split from the old symmetric PITCH_WATCHDOG_RAD constant because the leg linkage collides with the ground at a different forward angle than backward. Requires pitch_watchdog_en=1.'), 1091: ('pitch_wd_bwd_ret', 'Pitch watchdog backward trip threshold, fully retracted leg [rad, magnitude]. ESTOPs (FAULT_PITCH_WATCHDOG) if pitch < -this value for > 200 ms. Gain-scheduled toward pitch_watchdog_bwd_ext by the same alpha as the LQR gains. Split from the old symmetric PITCH_WATCHDOG_RAD constant because the leg linkage collides with the ground at a different backward angle than forward. Requires pitch_watchdog_en=1.'), 1092: ('pitch_wd_fwd_ext', 'Pitch watchdog forward trip threshold, fully extended leg [rad, magnitude]. Companion to pitch_watchdog_fwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1093: ('pitch_wd_bwd_ext', 'Pitch watchdog backward trip threshold, fully extended leg [rad, magnitude]. Companion to pitch_watchdog_bwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1280: ('radio_hip_cmd', 'Hip extension command from CH3 [0=retracted, 1=extended]; firmware-written, stale when the radio link is dead.'), 1281: ('radio_vel_max', "Max forward speed mapped from full CH2 deflection [m/s]. READONLY — copied from the active CH9 profile's vel_max. Edit profile1/2/3_vel_max instead."), 1282: ('radio_yaw_max', "Max yaw rate mapped from full CH4 deflection [rad/s]. READONLY — copied from the active CH9 profile's yaw_max. Edit profile1/2/3_yaw_max instead."), 1283: ('live_tune_ch7_val', 'Live-tune shadow value for CH7\'s knob, mapped into whatever param CH7 is currently wired to for the CH5/CH6-selected group in main.cpp\'s LIVE_TUNE_SLOTS table (see live_tune.h) — group 0 lqr_k_pitch_ret [-0.1,-2.0] (widened 2026-07-26; the 2026-07-25 bench run pegged the old -0.5 end stop), group 1 vel_pi_kp [0.05,1.0], group 2 roll_kp [0.3,4.0]. min/max here is the union across all three groups\' ranges, display-only — the firmware write uses param_force_set and is never clamped by this param\'s own bounds. Only takes effect (overrides the real param in the control loop) once the knob has been swept through the active group\'s target\'s current value ("pickup", avoids a step change) and live-tune mode is active (RUNNING + calibration switch up). Write live_tune_latch=1 to persist the shadow into the real param. Firmware-written, stale when the radio link is dead.'), 1307: ('live_tune_ch8_val', "Live-tune shadow value for CH8's knob — same mechanism as live_tune_ch7_val, min/max is likewise the display-only union across groups (group 0 lqr_k_rate_ret [-0.01,-1.0], widened 2026-07-26 alongside CH7 so the rate/pitch ratio stays reachable as k_pitch grows; group 1 vel_pi_ki [0.02,0.5]; group 2 roll_kd [0.02,0.5]). See LIVE_TUNE_SLOTS in main.cpp."), 1296: ('profile1_vel_max', 'Speed profile 1 (slow) max forward speed [m/s]; CH9 3-position switch selects the active profile.'), 1297: ('profile1_yaw_max', 'Speed profile 1 (slow) max yaw rate [rad/s].'), 1298: ('profile1_torque_lim', 'Speed profile 1 (slow) LQR torque limit [N·m].'), 1299: ('profile2_vel_max', 'Speed profile 2 (normal) max forward speed [m/s].'), 1300: ('profile2_yaw_max', 'Speed profile 2 (normal) max yaw rate [rad/s].'), 1301: ('profile2_torque_lim', 'Speed profile 2 (normal) LQR torque limit [N·m].'), 1302: ('profile3_vel_max', 'Speed profile 3 (fast) max forward speed [m/s].'), 1303: ('profile3_yaw_max', 'Speed profile 3 (fast) max yaw rate [rad/s].'), 1304: ('profile3_torque_lim', 'Speed profile 3 (fast) LQR torque limit [N·m].'), 1305: ('active_profile', 'Active speed profile index (0/1/2), selected by CH9; firmware-written, READONLY.'), 1306: ('live_tune_latch', "Write 1 while live-tuning (RUNNING + calibration switch up) to persist every currently-picked-up LIVE_TUNE_SLOTS entry's shadow value into its real param. One-shot: firmware performs the latch(es) and resets this to 0. Slots that haven't picked up yet (knob never swept through the target's current value) are skipped, not latched at their un-picked-up shadow value. Ignored outside live-tune mode."), 1308: ('roll_ctrl_en', '1 = enable the roll controller: a PD loop on roll angle/rate that adds a differential hip position offset (extend one leg, retract the other) to level/lean the body. Active only in RUNNING. Default off — with it off the hips are held symmetrically exactly as before.'), 1309: ('roll_kp', 'Roll PD proportional gain: hip position offset [rad] per rad of roll error (roll_cmd_rad - measured roll).'), 1310: ('roll_kd', 'Roll PD derivative gain: hip position offset [rad] per rad/s of measured roll rate (damping term).'), 1311: ('roll_offset_max', 'Clamp on the differential hip position offset [rad] produced by the roll PD loop, applied +offset to one hip and -offset to the other. Bounds how far a bad gain can drive the legs apart; also clamped to calibrated hip travel.'), 1312: ('roll_rate_lim', "Slew-rate limit [rad/s] on the roll setpoint (roll_cmd_rad) before it enters the PD loop, so a snapped stick doesn't step-perturb the pitch balancer."), 1313: ('roll_watchdog_en', "1 = ESTOP (FAULT_ROLL_WATCHDOG) if |roll| > roll_watchdog_limit for > 200 ms (lateral tip guard). Default off, persistent across reboot and reflash (changed 2026-07-26 — was default-on and non-persistent specifically so a bench-test disable couldn't silently survive into a real run; that safety property no longer holds now that this is persisted default-off)."), 1314: ('roll_watchdog_limit', '|roll| threshold [rad] that trips FAULT_ROLL_WATCHDOG after 200 ms (default ~20°). Set well inside the lateral tip-over angle.'), 1315: ('hip_roll_kp', 'Hip MIT position gain [N·m/rad] used for the hip hold while the roll controller is active, replacing hip_running_kp. Set soft so the legs are backdrivable by obstacles (active suspension); keep hip_running_tff high enough that the legs still hold height under load.'), 1316: ('hip_roll_kd', 'Hip MIT damping gain [N·m·s/rad] used for the hip hold while the roll controller is active, replacing hip_running_kd.'), 1317: ('roll_cmd_rad', 'Roll setpoint [rad] from CH1, = CH1_norm * radio_roll_max; firmware-written, zeroed when the radio link is dead. READONLY.'), 1318: ('radio_roll_max', "Max roll setpoint mapped from full CH1 deflection [rad]. READONLY — copied from the active CH9 profile's roll_max. Edit profile1/2/3_roll_max instead."), 1319: ('profile1_roll_max', 'Speed profile 1 (slow) max roll setpoint [rad]; CH9 selects the active profile. Conservative — well inside the lateral tip angle.'), 1320: ('profile2_roll_max', 'Speed profile 2 (normal) max roll setpoint [rad].'), 1321: ('profile3_roll_max', 'Speed profile 3 (fast/aggressive) max roll setpoint [rad] (~10°).')}
